#include "fedspatial/gpu_context.hpp"
#include <algorithm>
#include <algorithm>
#include <iostream>
using namespace fedspatial;static bool ld(const std::string&n,Matrix*x){return read_matrix("sync_gpu/tests/fixtures/sync_gpu/"+n,x);}static double e(const std::string&n,const Matrix&v){Matrix r;if(!ld(n,&r))throw 1;return max_abs_diff(v,r);}int main(){Matrix k(2,2),s(3,2),z(3,1),x(3,1),g(1,1),mu(2,1),sg(2,2);double a[]={0,0,1,.2,.3,1.1},b[]={0,0,1.5,1.5},q[]={1.2,-.4,.7};std::copy(a,a+6,s.a.begin());std::copy(b,b+4,k.a.begin());std::copy(q,q+3,z.a.begin());for(double&v:x.a)v=1;g(0,0)=.15;mu(0,0)=.2;mu(1,0)=-.1;sg(0,0)=.7;sg(1,1)=.4;sg(0,1)=sg(1,0)=.05;GpuContext c(0);double wk=0,wc=0,wb=0,ws=0;try{for(int i=0;i<7;i++){Matrix p;if(!ld("DELTA_THETA_POINT"+std::to_string(i)+"_PARAM.txt",&p))return 2;std::string h="DELTA_THETA_POINT"+std::to_string(i)+"_";auto d=compute_b_second_derivatives(c,{s,z,x},k,{g,mu,sg,p(0,0),p(1,0),p(2,0)});wk=std::max({wk,e(h+"K_HESS_AA.txt",d.kaa),e(h+"K_HESS_AR.txt",d.kar),e(h+"K_HESS_RR.txt",d.krr)});wc=std::max({wc,e(h+"CROSS_HESS_AA.txt",d.caa),e(h+"CROSS_HESS_AR.txt",d.car),e(h+"CROSS_HESS_RR.txt",d.crr)});wb=std::max({wb,e(h+"B_HESS_AA.txt",d.baa),e(h+"B_HESS_AR.txt",d.bar),e(h+"B_HESS_RA.txt",d.bra),e(h+"B_HESS_RR.txt",d.brr)});ws=std::max(ws,max_abs_diff(d.bar,d.bra));}}catch(...){return 2;}std::cout<<"K_HESS_MAX_ABS_ERROR="<<wk<<"\nCROSS_HESS_MAX_ABS_ERROR="<<wc<<"\nB_HESS_MAX_ABS_ERROR="<<wb<<"\nB_HESS_SYMMETRY_MAX_ABS_ERROR="<<ws<<"\nB_HESS_PARITY="<<((wb<=1e-8&&wk<=1e-10&&wc<=1e-10&&ws<=1e-10)?"PASS":"FAIL")<<"\n";return wb<=1e-8&&wk<=1e-10&&wc<=1e-10&&ws<=1e-10?0:1;}
